// Message timestamps are generated by the server, but the client's
// clock may disagree with the server's. We track that difference so
// that deadlines computed from message timestamps match the ones
// the server will actually enforce.

let clock_offset_seconds = 0;

export function update_offset(server_timestamp: number, rtt_seconds = 0): void {
    if (rtt_seconds < 0 || rtt_seconds > 5) {
        return;
    }
    clock_offset_seconds = server_timestamp + rtt_seconds / 2 - Date.now() / 1000;
}

export function now(): number {
    return Date.now() / 1000 + clock_offset_seconds;
}

export function _reset_for_testing(): void {
    clock_offset_seconds = 0;
}
